// ==============================================================================
// ZYRVAE WF-02: CSV Parsing, Header Validation, and In-Batch Deduplication
// ==============================================================================
const items = $input.all();
const ALLOWED_HEADERS = new Set([
  'business_name',
  'website_url',
  'country',
  'industry',
  'source',
  'source_url',
  'evidence_notes'
]);

let csvText = '';
// Si el trigger o nodo anterior envía datos binarios (archivo CSV)
if (items[0] && items[0].binary && items[0].binary.data) {
  csvText = Buffer.from(items[0].binary.data.data, 'base64').toString('utf8');
} else if (items[0] && items[0].json && items[0].json.csv_data) {
  csvText = items[0].json.csv_data;
} else {
  // CSV de prueba sintético por defecto si se ejecuta sin archivo
  csvText = `business_name,website_url,country,industry,source,source_url,evidence_notes
"[TEST-01] Valid Tech Corp",https://example.com,AR,Technology,CSV_IMPORT,https://test.zyrvae.internal/leads.csv,"Valid test lead"
"[TEST-02] Broken Server SA",https://httpbin.org/status/503,CL,Retail,CSV_IMPORT,https://test.zyrvae.internal/leads.csv,"HTTP 503 test"
"[TEST-03] Malformed Lead",not-a-valid-domain,UY,Consulting,CSV_IMPORT,https://test.zyrvae.internal/leads.csv,"Malformed URL"
"[TEST-04] Duplicate Tech Corp",https://example.com,AR,Technology,CSV_IMPORT,https://test.zyrvae.internal/leads.csv,"Duplicate test"
"",,,,,"Empty row test"
"[TEST-05] SSRF Trap Inc",http://127.0.0.1:8080/admin,MX,Security,CSV_IMPORT,https://test.zyrvae.internal/leads.csv,"SSRF test"`;
}

// Función simple y robusta para parsing CSV con soporte de comillas
function parseCSV(text) {
  const lines = text.split(/\r?\n/).filter(line => line.trim().length > 0);
  if (lines.length === 0) return { headers: [], rows: [] };

  function splitRow(rowStr) {
    const regex = /(?:\"([^\"]*(?:\"\"[^\"]*)*)\"|([^,]+)|(?=,))(?:,|$)/g;
    const result = [];
    let match;
    while ((match = regex.exec(rowStr)) !== null) {
      if (match.index === regex.lastIndex) regex.lastIndex++;
      let val = match[1] !== undefined ? match[1].replace(/""/g, '"') : (match[2] !== undefined ? match[2] : '');
      result.push(val.trim());
      if (regex.lastIndex >= rowStr.length && rowStr.endsWith(',')) {
        result.push('');
        break;
      }
    }
    return result;
  }

  const rawHeaders = splitRow(lines[0]).map(h => h.toLowerCase().trim());
  const rows = [];
  for (let i = 1; i < lines.length; i++) {
    const values = splitRow(lines[i]);
    const rowObj = {};
    rawHeaders.forEach((h, idx) => {
      rowObj[h] = values[idx] || '';
    });
    rows.push({ rowIndex: i + 1, data: rowObj });
  }
  return { headers: rawHeaders, rows };
}

const parsed = parseCSV(csvText);
const validLeads = [];
const skippedErrors = [];
const seenUrls = new Set();

for (const row of parsed.rows) {
  const bName = (row.data.business_name || '').trim();
  let wUrl = (row.data.website_url || '').trim();

  // Validación 1: Fila vacía
  if (!bName && !wUrl) {
    skippedErrors.push({ row: row.rowIndex, error: 'EMPTY_ROW', reason: 'Fila sin nombre ni web', raw: row.data });
    continue;
  }

  // Validación 2: Nombre obligatorio
  if (!bName) {
    skippedErrors.push({ row: row.rowIndex, error: 'MISSING_BUSINESS_NAME', reason: 'Nombre de empresa ausente', raw: row.data });
    continue;
  }

  // Validación 3: Formato URL
  if (wUrl) {
    if (!wUrl.startsWith('http://') && !wUrl.startsWith('https://')) {
      if (wUrl.includes('.') && !wUrl.includes(' ')) {
        wUrl = 'https://' + wUrl;
      } else {
        skippedErrors.push({ row: row.rowIndex, error: 'INVALID_URL_SYNTAX', reason: 'Sintaxis de URL inválida', raw: row.data });
        continue;
      }
    }
  }

  // Validación 4: Deduplicación in-batch
  const normUrl = wUrl.toLowerCase().replace(/\/+$/, '');
  if (normUrl && seenUrls.has(normUrl)) {
    skippedErrors.push({ row: row.rowIndex, error: 'IN_BATCH_DUPLICATE', reason: 'URL duplicada dentro del archivo', raw: row.data });
    continue;
  }
  if (normUrl) seenUrls.add(normUrl);

  validLeads.push({
    json: {
      row_index: row.rowIndex,
      business_name: bName,
      website_url: wUrl,
      country: (row.data.country || '').trim(),
      industry: (row.data.industry || '').trim(),
      source: (row.data.source || 'CSV_IMPORT').trim(),
      source_url: (row.data.source_url || '').trim(),
      evidence_notes: (row.data.evidence_notes || '').trim(),
      batch_id: $execution.id || 'manual-batch'
    }
  });
}

// Guardar errores de parsing en variable global de ejecución o salida
return validLeads;

// ==============================================================================
// SSRF & Safety Guard: Bloquea destinos locales, privados o metadata
// ==============================================================================
const item = $input.item.json;
const urlStr = item.normalized_website_url || item.website_url;

function checkSSRF(url) {
  if (!url) return { safe: false, reason: 'URL ausente' };
  try {
    const parsed = new URL(url);
    if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
      return { safe: false, reason: `Protocolo no permitido: ${parsed.protocol}` };
    }
    const host = parsed.hostname.toLowerCase();
    if (['localhost', '127.0.0.1', '::1', '0.0.0.0'].includes(host)) {
      return { safe: false, reason: 'Host de loopback bloqueado' };
    }
    if (host.startsWith('10.') || host.startsWith('192.168.') || host.startsWith('169.254.')) {
      return { safe: false, reason: 'Red privada / metadata bloqueada' };
    }
    if (host.match(/^172\.(1[6-9]|2[0-9]|3[0-1])\./)) {
      return { safe: false, reason: 'Red privada RFC 1918 bloqueada' };
    }
    return { safe: true, reason: null };
  } catch (e) {
    return { safe: false, reason: 'Error parseando URL' };
  }
}

const check = checkSSRF(urlStr);
return {
  json: {
    ...item,
    audit_target_url: urlStr,
    is_ssrf_safe: check.safe,
    ssrf_block_reason: check.reason
  }
};

// ==============================================================================
// Extraer evidencia técnica objetiva y formular hipótesis comerciales factibles
// ==============================================================================
const item = $input.item.json;
const leadData = $('SSRF Security Filter').first().json;

const statusCode = item.statusCode || item.status || null;
const headers = item.headers || {};
const body = typeof item.body === 'string' ? item.body : '';
const url = leadData.audit_target_url;

// Extracción HTML mediante expresiones regulares seguras
const titleMatch = body.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
const title = titleMatch ? titleMatch[1].trim() : null;

const metaDescMatch = body.match(/<meta[^>]+name=['"]description['"][^>]+content=['"]([\s\S]*?)['"]/i) ||
                      body.match(/<meta[^>]+content=['"]([\s\S]*?)['"][^>]+name=['"]description['"]/i);
const metaDescription = metaDescMatch ? metaDescMatch[1].trim() : null;

const viewportMatch = body.match(/<meta[^>]+name=['"]viewport['"]/i);
const hasViewport = Boolean(viewportMatch);

const sslActive = url.startsWith('https://');
const isAccessible = statusCode >= 200 && statusCode < 400;

// Hipótesis comerciales basadas estrictamente en la evidencia
const hypotheses = [];
if (!sslActive) {
  hypotheses.push({
    category: 'SECURITY_SSL',
    evidence: 'Sitio opera sin HTTPS por defecto',
    opportunity: 'Migración y securización con certificado SSL'
  });
}
if (!hasViewport) {
  hypotheses.push({
    category: 'MOBILE_RESPONSIVE',
    evidence: 'Falta etiqueta meta viewport para diseño responsivo',
    opportunity: 'Optimización de interfaz móvil (Mobile UX / RWD)'
  });
}
if (!metaDescription) {
  hypotheses.push({
    category: 'SEO_ONPAGE',
    evidence: 'No posee meta description declarada en HTML',
    opportunity: 'Optimización de snippets de búsqueda SEO on-page'
  });
}
if (statusCode && statusCode >= 400) {
  hypotheses.push({
    category: 'SITE_HEALTH',
    evidence: `El servidor web respondió con código de error HTTP ${statusCode}`,
    opportunity: 'Recuperación de disponibilidad web y diagnóstico de hosting'
  });
}

return {
  json: {
    lead_id: leadData.lead_id || leadData.id || `lead-temp-${leadData.row_index}`,
    initial_url: url,
    final_url: item.url || url,
    http_status: statusCode,
    page_title: title,
    meta_description: metaDescription,
    has_viewport: hasViewport,
    ssl_active: sslActive,
    is_accessible: isAccessible,
    error_code: isAccessible ? null : (statusCode ? `HTTP_ERROR_${statusCode}` : 'NETWORK_ERROR'),
    commercial_hypotheses: hypotheses,
    raw_evidence: {
      status_code: statusCode,
      content_length: body.length,
      server: headers['server'] || null
    }
  }
};

// Manejo para URLs bloqueadas por SSRF
const leadData = $('SSRF Security Filter').first().json;
return {
  json: {
    lead_id: leadData.lead_id || leadData.id || `lead-temp-${leadData.row_index}`,
    initial_url: leadData.audit_target_url,
    final_url: null,
    http_status: null,
    page_title: null,
    meta_description: null,
    has_viewport: false,
    ssl_active: false,
    is_accessible: false,
    error_code: 'SSRF_BLOCKED',
    commercial_hypotheses: [],
    raw_evidence: { reason: leadData.ssrf_block_reason }
  }
};

// ==============================================================================
// Preparar registro para persistencia en website_audits
// ==============================================================================
const item = $input.item.json;
const auditRecord = {
  id: 'aud_' + Math.random().toString(36).substring(2, 15),
  lead_id: item.lead_id,
  audit_date: new Date().toISOString(),
  initial_url: item.initial_url,
  final_url: item.final_url,
  http_status: item.http_status,
  redirect_count: 0,
  response_time_ms: null,
  page_title: item.page_title,
  meta_description: item.meta_description,
  has_viewport: item.has_viewport,
  ssl_active: item.ssl_active,
  is_accessible: item.is_accessible,
  error_code: item.error_code,
  raw_evidence: JSON.stringify(item.raw_evidence),
  commercial_hypotheses: JSON.stringify(item.commercial_hypotheses)
};

return { json: auditRecord };
